        const normalized = this.normalizeInputs(trace, R, S, sqlObj, telemetryData);
        trace = normalized.trace;
        R = normalized.R;
        S = normalized.S;
        sqlObj = normalized.sqlObj;
        telemetryData = normalized.telemetryData;

